function Config.GiftData.data_gift_data_fun(slot0)
	slot1 = Config.GiftData.data_gift_data[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.GiftData.data_gift_data[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

